def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, r + 1, nc, color))
    for r1, c1, r2, c2, color in pairs:
        dr, dc = r2 - r1, c2 - c1
        before = (r1 - dr, c1 - dc)
        after = (r2 + dr, c2 + dc)
        before_open = (0 <= before[0] < h and 0 <= before[1] < w and grid[before[0]][before[1]] == background)
        after_open = (0 <= after[0] < h and 0 <= after[1] < w and grid[after[0]][after[1]] == background)
        for start, sr, sc, is_open in ((before, -dr, -dc, before_open), (after, dr, dc, after_open)):
            if not is_open:
                continue
            r, c = start
            while 0 <= r < h and 0 <= c < w and out[r][c] == background:
                out[r][c] = color
                r += sr
                c += sc
    return out
